with card_content(display_order, question_text, question_translation, answer_examples) as (
  values
    (51, 'Do you prefer coffee or tea?', 'Você prefere café ou chá?', '[{"answer":"I prefer coffee.","translation":"Eu prefiro café.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"Tea, definitely.","translation":"Chá, com certeza.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I like both, but I drink more coffee.","translation":"Eu gosto dos dois, mas tomo mais café.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I usually drink coffee in the morning and tea at night.","translation":"Eu geralmente tomo café de manhã e chá à noite.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"It depends on the weather, but most days I choose coffee.","translation":"Depende do clima, mas na maioria dos dias escolho café.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (52, 'What is your favorite drink?', 'Qual é a sua bebida favorita?', '[{"answer":"My favorite drink is coffee.","translation":"Minha bebida favorita é café.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I really like orange juice.","translation":"Eu gosto muito de suco de laranja.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I usually prefer sparkling water.","translation":"Eu geralmente prefiro água com gás.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I love fresh fruit juice.","translation":"Eu adoro suco de fruta natural.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"For everyday drinks, coffee is probably my favorite.","translation":"Entre as bebidas do dia a dia, café provavelmente é a minha favorita.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (53, 'Do you like trying new foods?', 'Você gosta de experimentar comidas novas?', '[{"answer":"Yes, I love trying new foods.","translation":"Sim, eu adoro experimentar comidas novas.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"Yes, especially when I travel.","translation":"Sim, especialmente quando viajo.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"Sometimes, if the dish looks interesting.","translation":"Às vezes, se o prato parecer interessante.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I''m a little cautious, but I try new things.","translation":"Eu sou um pouco cauteloso/a, mas experimento coisas novas.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"Not very much. I usually prefer food I already know.","translation":"Não muito. Eu geralmente prefiro comidas que já conheço.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (54, 'What is your favorite restaurant?', 'Qual é o seu restaurante favorito?', '[{"answer":"My favorite restaurant is a small Italian place near my house.","translation":"Meu restaurante favorito é um pequeno restaurante italiano perto da minha casa.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I really like a local steakhouse.","translation":"Eu gosto muito de uma churrascaria local.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I don''t have one favorite restaurant.","translation":"Eu não tenho um restaurante favorito.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"There''s a Japanese restaurant downtown that I love.","translation":"Há um restaurante japonês no centro de que eu gosto muito.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"My favorite place changes, but I usually choose restaurants with good homemade food.","translation":"Meu lugar favorito muda, mas geralmente escolho restaurantes com boa comida caseira.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (55, 'Do you like traveling?', 'Você gosta de viajar?', '[{"answer":"Yes, I love traveling.","translation":"Sim, eu adoro viajar.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"Yes, especially to new places.","translation":"Sim, especialmente para lugares novos.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I enjoy short trips on weekends.","translation":"Eu gosto de viagens curtas nos fins de semana.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"Sometimes, but I also like staying home.","translation":"Às vezes, mas também gosto de ficar em casa.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"Yes, traveling is one of my favorite ways to spend my vacation.","translation":"Sim, viajar é uma das minhas formas favoritas de passar as férias.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (56, 'What countries have you visited?', 'Quais países você já visitou?', '[{"answer":"I''ve visited Argentina and Chile.","translation":"Eu já visitei Argentina e Chile.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I''ve been to the United States.","translation":"Eu já fui aos Estados Unidos.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I''ve visited Portugal and Spain.","translation":"Eu já visitei Portugal e Espanha.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I haven''t traveled abroad yet.","translation":"Eu ainda não viajei para fora do país.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I''ve visited a few countries in South America and Europe.","translation":"Eu já visitei alguns países na América do Sul e na Europa.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (57, 'What is your favorite place you have visited?', 'Qual é o seu lugar favorito entre os que você já visitou?', '[{"answer":"My favorite place was Rio de Janeiro.","translation":"Meu lugar favorito foi o Rio de Janeiro.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I loved visiting Buenos Aires.","translation":"Eu adorei visitar Buenos Aires.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"The beach I visited last year was amazing.","translation":"A praia que visitei no ano passado foi incrível.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"So far, my favorite place is Lisbon.","translation":"Até agora, meu lugar favorito é Lisboa.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"It''s difficult to choose, but a small mountain town I visited was unforgettable.","translation":"É difícil escolher, mas uma pequena cidade nas montanhas que visitei foi inesquecível.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (58, 'Where would you like to travel next?', 'Para onde você gostaria de viajar na próxima vez?', '[{"answer":"I''d like to go to Italy.","translation":"Eu gostaria de ir para a Itália.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I want to visit Canada next.","translation":"Eu quero visitar o Canadá na próxima viagem.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I''d love to travel to Japan.","translation":"Eu adoraria viajar para o Japão.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"Maybe somewhere in the northeast of Brazil.","translation":"Talvez algum lugar no Nordeste do Brasil.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"My next trip will probably be somewhere with beaches and warm weather.","translation":"Minha próxima viagem provavelmente será para algum lugar com praias e clima quente.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (59, 'What is your dream destination?', 'Qual é o destino dos seus sonhos?', '[{"answer":"My dream destination is Japan.","translation":"O destino dos meus sonhos é o Japão.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I''d love to visit New Zealand.","translation":"Eu adoraria visitar a Nova Zelândia.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I''ve always wanted to go to Italy.","translation":"Eu sempre quis ir para a Itália.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I dream of seeing the Northern Lights.","translation":"Eu sonho em ver a aurora boreal.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"My dream trip would be a long journey through several European countries.","translation":"Minha viagem dos sonhos seria uma longa jornada por vários países europeus.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (60, 'Do you prefer the beach or the mountains?', 'Você prefere praia ou montanhas?', '[{"answer":"I prefer the beach.","translation":"Eu prefiro a praia.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I definitely prefer the mountains.","translation":"Eu definitivamente prefiro as montanhas.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I like both, but I choose the beach in summer.","translation":"Eu gosto dos dois, mas escolho a praia no verão.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"The mountains, because I enjoy cooler weather.","translation":"As montanhas, porque eu gosto de clima mais fresco.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"It depends on the trip, but I usually feel more relaxed at the beach.","translation":"Depende da viagem, mas geralmente me sinto mais relaxado/a na praia.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb)
)
update public.conversation_questions as question
set question_text=content.question_text, question_translation=content.question_translation, answer_examples=content.answer_examples
from card_content as content where question.display_order=content.display_order;
